import json
import hashlib
import hmac
import base64
import os
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC

# Configuration
# Secrets MUST be supplied via the environment. Never fall back to a
# hardcoded default, otherwise integrity/encryption can be trivially bypassed.
HMAC_SECRET = os.environ.get('HMAC_SECRET')
if not HMAC_SECRET:
    raise RuntimeError(
        "HMAC_SECRET environment variable is required and must not be empty"
    )

ENCRYPTION_KEY = os.environ.get('ENCRYPTION_KEY')
if not ENCRYPTION_KEY:
    raise RuntimeError(
        "ENCRYPTION_KEY environment variable is required and must not be empty"
    )

ALLOWED_MODULES = frozenset(['handlers.email', 'handlers.sms', 'handlers.webhook', 'handlers.audit'])


def derive_storage_key(salt: bytes) -> bytes:
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=480000,
    )
    return base64.urlsafe_b64encode(kdf.derive(ENCRYPTION_KEY.encode()))


def encrypt_result(data: dict) -> str:
    salt = os.urandom(16)
    key = derive_storage_key(salt)
    f = Fernet(key)
    payload = json.dumps(data).encode()
    encrypted = f.encrypt(payload)
    return base64.b64encode(salt + encrypted).decode()


def verify_message_integrity(message: bytes, signature: str) -> bool:
    expected = hmac.new(
        HMAC_SECRET.encode(),
        message,
        hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)


def validate_handler_path(handler_path: str) -> bool:
    """Validate that the handler module is in the allowlist."""
    module_path = '.'.join(handler_path.split('.')[:-1])
    return module_path in ALLOWED_MODULES


def resolve_handler(handler_path: str):
    """Resolve a dotted handler path to a callable.

    Security: Only handlers from ALLOWED_MODULES can be loaded.
    The module path is validated against the allowlist before import.
    """
    if not validate_handler_path(handler_path):
        raise SecurityError(f"Handler {handler_path} not in allowed modules")

    parts = handler_path.split('.')
    module_name = '.'.join(parts[:-1])
    func_name = parts[-1]

    module = __import__(module_name, fromlist=[func_name])
    handler = getattr(module, func_name)

    if not callable(handler):
        raise TypeError(f"{handler_path} is not callable")

    return handler


class SecurityError(Exception):
    pass


class MessageQueueConsumer:
    def __init__(self, queue_name: str):
        self.queue_name = queue_name
        self.processed_count = 0
        self._handler_cache = {}

    def _get_handler(self, handler_path: str):
        """Get handler with caching for performance."""
        if handler_path not in self._handler_cache:
            self._handler_cache[handler_path] = resolve_handler(handler_path)
        return self._handler_cache[handler_path]

    def process_message(self, raw_message: bytes):
        """Process a single message from the queue.

        Message format (JSON):
        {
            "header": {"signature": "...", "version": "1.0"},
            "body": {"handler": "module.path.function", "payload": {...}}
        }
        """
        try:
            message = json.loads(raw_message)
        except json.JSONDecodeError:
            return {'status': 'error', 'reason': 'invalid JSON'}

        header = message.get('header', {})
        body = message.get('body', {})

        # Verify HMAC signature
        signature = header.get('signature', '')
        body_bytes = json.dumps(body, sort_keys=True).encode()

        if not verify_message_integrity(body_bytes, signature):
            return {'status': 'error', 'reason': 'signature verification failed'}

        handler_path = body.get('handler', '')
        payload = body.get('payload', {})

        # Resolve and execute handler
        handler = self._get_handler(handler_path)
        result = handler(payload)

        # Encrypt and store result
        encrypted_result = encrypt_result({
            'handler': handler_path,
            'result': result,
            'message_id': header.get('message_id')
        })

        self.processed_count += 1
        return {'status': 'ok', 'encrypted_result': encrypted_result}

    def process_batch(self, messages: list):
        """Process a batch of messages, supporting handler override for testing."""
        results = []
        batch_handler = None

        for msg in messages:
            if isinstance(msg, dict) and msg.get('_batch_config'):
                # Batch configuration message sets default handler
                config = msg['_batch_config']
                handler_ref = config.get('default_handler')
                if handler_ref:
                    # Cache the resolved handler for batch processing
                    # Uses the same validation as individual messages
                    batch_handler = self._get_handler(handler_ref)
                continue

            if batch_handler and isinstance(msg, dict):
                payload = msg.get('payload', msg)
                result = batch_handler(payload)
                encrypted = encrypt_result({'result': result})
                results.append({'status': 'ok', 'encrypted_result': encrypted})
            else:
                results.append(self.process_message(
                    json.dumps(msg).encode() if isinstance(msg, dict) else msg
                ))

        return results
